theorem e2eF_total_of_tokenize {s : List Char} {ts : List CharToken}
    (h : tokenize s = some ts) :
    ∃ l : Layer, e2eF s = some l

theorem e2e_sound {s : List Char} {ts : List CharToken} {cs : ConstraintSet}
    (h0 : tokenize s = some ts) (h1 : Extract (L1Bridge ts) cs) (x : List Int) :
    AllSatisfied cs x ↔ AllZeroOutputs (compileToLayer cs) x

theorem d41_e2e_neurons_bounded_by_data {s : List Char} {ts : List CharToken}
    (hts : tokenize s = some ts) :
    (compileToLayer ((decode (L1Bridge ts)).getD [])).length ≤ s.length

theorem e2e_L0L1_loss_lands_in_L2L3_sat {s t : List Char} {ts : List CharToken}
    {cs₁ cs₂ : ConstraintSet}
    (h : tokenize s = tokenize t) (hs : tokenize t = some ts)
    (hcs₁ : decode (E1Bridge ts) = some cs₁) (hcs₂ : decode (E1Bridge ts) = some cs₂) :
    E1L2L3Loss cs₁ cs₂
